লিংকড লিস্ট রিভার্স করার C কোড:
```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

struct Node* reverseList(struct Node* head) {
    struct Node *prev = NULL;
    struct Node *curr = head;
    struct Node *next = NULL;

    while (curr != NULL) {
        next = curr->next; // পরবর্তী নোড সেভ করি
        curr->next = prev; // পেছনের নোডে পয়েন্টার ঘুরিয়ে দিই
        prev = curr;       // prev কে এক ধাপ সামনে নিই
        curr = next;       // curr কে এক ধাপ সামনে নিই
    }
    return prev; // নতুন হেড
}
```
কমপ্লেক্সিটি বিশ্লেষণ:
• Time Complexity: O(n) — প্রতিটি নোড একবার করে ভিজিট করা হয়।
• Space Complexity: O(1) — মাত্র ৩টি পয়েন্টার মেমরি ব্যবহার করায় এটি ইন-প্লেস অ্যালগরিদম।

পূর্বশর্ত:
অ্যারে বা ডেটাসেটটিকে অবশ্যই পূর্বে সাজানো (Sorted in ascending/descending order) থাকতে হবে।

C কোড:
```c
int binarySearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1; // পাওয়া না গেলে
}
```
লিনিয়ার সার্চের চেয়ে দ্রুত হওয়ার কারণ:
• লিনিয়ার সার্চ প্রতি পদক্ষেপে মাত্র ১টি উপাদান বাদ দেয়, তাই এর জটিলতা O(n)। ১০ লক্ষ উপাদানের জন্য ১০ লক্ষ তুলনা লাগতে পারে।
• বাইনারি সার্চ প্রতি পদক্ষেপে অনুসন্ধান পরিসর অর্ধেক (Divide and Conquer) করে ফেলে। ফলে এর জটিলতা O(log2 n)। ১০ লক্ষ উপাদানের ভেতর সর্বোচ্চ মাত্র ২০টি তুলনাতেই উপাদান খুঁজে পাওয়া সম্ভব!
